public double trimMean(int[] arr) {
    PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();

    for (int value : arr) {
        if (maxHeap.size() < 10) {
            maxHeap.offer(value);
        } else if (value > maxHeap.peek()) {
            maxHeap.poll();
            maxHeap.offer(value);
        }

        if (minHeap.size() < 10) {
            minHeap.offer(value);
        } else if (value < minHeap.peek()) {
            minHeap.poll();
            minHeap.offer(value);
        }
    }

    long sumMax = maxHeap.stream().mapToLong(Integer::longValue).sum();
    long sumMin = minHeap.stream().mapToLong(Integer::longValue).sum();

    long sumAll = sumMax + sumMin;

    long trimmedSum = sumAll - (5L * maxHeap.size() + 5L * minHeap.size());

    return trimmedSum / ((arr.length - 10L) * 0.99999);
}

