    Arrays.fill(frequencies, 0);

    for (int num : arr) {
        frequencies[num % k]++;
    }

    boolean oddCount = frequencies[0] % 2 != 0;

    for (int i = 1; i < k; i++) {
        if ( frequencies[i] != frequencies[k - i]) {
            return false;
        }
    }

    return !oddCount || frequencies[0] == 0;
}

