    int n = cost.length;
    int[]	dp = new int[n];

    if (n <= 1) {
        return cost[0];
    }

    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return dp[n - 1];
}

