public static int minPerfectSquareSum(int n) {
    int a = (int) Math.sqrt(n);
    int min = n;
    for (int i = a; i > 0; i--) {
        int j = (int) Math.sqrt(n - i * i);
        int tmp = j * j + i * i;
        if (min > tmp) {
            min = tmp;
        }
    }
    return min;
}

